@dataclasses.dataclass
class SQLResult:
    lastrowid: int
    rowcount: int


class Application:
    def __init__(self, settings):
        self.cfg = settings
        self.lock = threading.RLock()
        self.condition = threading.Condition()
        self.stop_event = threading.Event()
        self.events = collections.deque(maxlen=256)
        self.sequence = 0
        self.stream_counts = collections.Counter()
        self.limits = {}
        self.limit_lock = threading.Lock()
        self.outbox_lock = threading.Lock()
        self.workers = []
        if settings.db_path != ":memory:":
            Path(settings.db_path).parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.db = sqlite3.connect(settings.db_path, check_same_thread=False, isolation_level=None, timeout=5)
        self.db.row_factory = sqlite3.Row
        self.db.executescript(SCHEMA)
        self.invalid_password = password_hash(secrets.token_urlsafe(24))
        try:
            self.migrate()
            self.bootstrap()
        except BaseException:
            self.db.close()
            raise

    def query(self, sql, *args):
        with self.lock:
            cursor = self.db.execute(sql, args)
            try:
                return [dict(row) for row in cursor.fetchall()]
            finally:
                cursor.close()

    def one(self, sql, *args):
        with self.lock:
            cursor = self.db.execute(sql, args)
            try:
                row = cursor.fetchone()
                return dict(row) if row is not None else None
            finally:
                cursor.close()

    def execute(self, sql, *args):
        with self.lock:
            cursor = self.db.execute(sql, args)
            result = SQLResult(cursor.lastrowid, cursor.rowcount)
            cursor.close()
            return result

    @contextlib.contextmanager
    def transaction(self):
        with self.lock:
            self.db.execute("BEGIN IMMEDIATE")
            try:
                yield
                self.db.execute("COMMIT")
            except BaseException:
                self.db.execute("ROLLBACK")
                raise

    def history(self, order_id, status, actor, comment="", stamp=None):
        self.execute("INSERT INTO history(order_id,status,actor_id,comment,created_at) VALUES (?,?,?,?,?)", order_id, status, actor, comment, stamp or now())

    def migrate(self):
        """Upgrade existing single-file installations without deleting data."""
        with self.transaction():
            columns = {row["name"] for row in self.query("PRAGMA table_info(users)")}
            first = "verification_status" not in columns
            for name, declaration in [("verification_status", "TEXT NOT NULL DEFAULT 'unverified'"),
                                      ("verification_note", "TEXT NOT NULL DEFAULT ''"),
                                      ("location_accuracy", "REAL")]:
                if name not in columns:
                    self.execute(f"ALTER TABLE users ADD COLUMN {name} {declaration}")
            if first:
                self.execute("UPDATE users SET approved=0,online=0 WHERE role='courier'")
                if self.cfg.demo:
                    self.execute("UPDATE users SET approved=1,verification_status='demo' WHERE role='courier' AND email IN ('artur@dropp.am','mariam@dropp.am','david@dropp.am','narek@dropp.am','ani@dropp.am','gor@dropp.am')")
            self.execute("UPDATE users SET vehicle='bike' WHERE vehicle NOT IN ('car','walk','bike')")

    def verified(self, user):
        return bool(user and user["role"] == "courier" and user["approved"] and
                    (user.get("verification_status") == "approved" or (self.cfg.demo and user.get("verification_status") == "demo")))

    def require_verified(self, user):
        if not self.verified(user):
            fail(403, "Загрузите селфи и фото паспорта, затем дождитесь проверки администратора.")

    def gps_fresh(self, user):
        if self.cfg.demo and user.get("verification_status") == "demo":
            return True
        try:
            stamp = dt.datetime.fromisoformat(user["located_at"].replace("Z", "+00:00")).timestamp()
            return user["lat"] is not None and user["lng"] is not None and -30 <= time.time() - stamp <= GPS_MAX_AGE
        except (ValueError, TypeError, KeyError, AttributeError):
            return False

    def identity_metadata(self, user_id):
        user = self.one("SELECT * FROM users WHERE id=? AND role='courier'", user_id)
        if not user:
            fail(404, "Курьер не найден.")
        record = self.one("SELECT submitted_at,consent_at FROM courier_identity WHERE user_id=?", user_id)
        revision = hashlib.sha256(f"{user_id}:{record['submitted_at']}".encode()).hexdigest() if record else None
        return {"user": safe_user(user), "submitted_at": record["submitted_at"] if record else None,
                "has_documents": bool(record), "revision": revision,
                "selfie": f"/api/courier/verification/media/{user_id}/selfie?revision={revision}" if record else None,
                "passport": f"/api/courier/verification/media/{user_id}/passport?revision={revision}" if record else None}

    def bootstrap(self):
        with self.transaction():
            mode = self.one("SELECT value FROM settings WHERE key='install_mode'")
            expected = "demo" if self.cfg.demo else "live"
            if mode and mode["value"] != expected:
                raise ValueError("Для перехода между demo и production задайте НОВЫЙ DB_PATH.")
            self.execute("INSERT OR IGNORE INTO settings(key,value) VALUES ('install_mode',?)", expected)
            if not self.one("SELECT id FROM users WHERE role='admin'"):
                password = self.cfg.admin_password or (DEMO_PASSWORD if self.cfg.demo else secrets.token_urlsafe(24))
                self.execute("INSERT INTO users(role,name,email,phone,password,created_at) VALUES (?,?,?,?,?,?)", "admin", "Арман Саркисян", self.cfg.admin_email, "+374 91 000 100", password_hash(password), now())
                if not self.cfg.demo and not self.cfg.admin_password:
                    print("Initial admin password (save now): " + password, flush=True)
            if self.cfg.demo and not self.one("SELECT id FROM users WHERE role='courier'"):
                self.seed_demo()

