        def test_20_identity_is_private_and_requires_review(self):
            account = Client(type(self))
            self.assertEqual(account.call("/auth/register", "POST", {"name": "Проверка Документов", "email": "identity@test.am", "phone": "+374 91 220 001", "password": password, "role": "courier", "vehicle": "walk"})[0], 200)
            target = account.user["id"]
            self.assertEqual(self.admin.call(f"/users/{target}/approve", "POST", {"confirmed": True})[0], 409)
            self.assertEqual(account.call("/courier/location", "POST", {"lat": 40.18, "lng": 44.51})[0], 403)
            self.assertEqual(account.call("/courier/verification", "POST", {"selfie": photo, "passport": photo, "vehicle": "walk", "consent": False})[0], 400)
            self.assertEqual(account.call("/courier/verification", "POST", {"selfie": photo, "vehicle": "walk", "consent": True})[0], 400)
            self.assertEqual(account.call("/courier/verification", "POST", {"selfie": photo, "passport": photo, "vehicle": "scooter", "consent": True})[0], 400)
            self.assertEqual(account.call("/courier/verification", "POST", {"selfie": photo, "passport": photo, "vehicle": "walk", "consent": True})[0], 200)
            original_revision = self.admin.call(f"/users/{target}/verification")[1]["revision"]
            self.assertEqual(self.admin.call(f"/users/{target}/approve", "POST", {})[0], 400)
            for part in ("selfie", "passport"):
                path = f"/courier/verification/media/{target}/{part}"
                own = account.call(path)
                self.assertEqual(own[0], 200)
                self.assertIn("no-store", own[2]["Cache-Control"])
                self.assertEqual(self.admin.call(path)[0], 200)
                self.assertEqual(self.bob.call(path)[0], 403)
                self.assertEqual(self.loser.call(path)[0], 403)
            self.assertEqual(self.bob.call(f"/users/{target}/verification")[0], 403)
            self.assertEqual(self.admin.call(f"/users/{target}/reject", "POST", {"reason": "Фото размыто"})[0], 200)
            self.assertEqual(account.call("/me")[1]["user"]["verification_note"], "Фото размыто")
            self.assertEqual(account.call("/courier/online", "POST", {"online": True})[0], 403)
            # Existing couriers may have orders before this upgrade; they must be
            # able to submit fresh documents while those orders are assigned.
            legacy_order = self.application.one("SELECT id FROM orders WHERE status='new' LIMIT 1")["id"]
            self.application.execute("UPDATE orders SET status='assigned',courier_id=? WHERE id=?", target, legacy_order)
            self.assertEqual(account.call("/courier/verification", "POST", {"selfie": photo, "passport": photo, "vehicle": "bike", "consent": True})[0], 200)
            self.assertEqual(self.admin.call(f"/users/{target}/approve", "POST", {"confirmed": True, "revision": original_revision})[0], 409)
            self.assertEqual(account.call(f"/courier/verification/media/{target}/selfie?revision={original_revision}")[0], 409)
            revision = self.admin.call(f"/users/{target}/verification")[1]["revision"]
            self.assertEqual(self.admin.call(f"/users/{target}/approve", "POST", {"confirmed": True, "revision": revision})[0], 200)
            self.assertEqual(account.call("/courier/location", "POST", {"lat": 40.18, "lng": 44.51})[0], 200)
            self.assertEqual(account.call("/courier/online", "POST", {"online": True})[0], 200)
            self.assertEqual(account.call("/courier/verification", "DELETE", {})[0], 409)
            self.application.execute("UPDATE orders SET status='cancelled' WHERE id=?", legacy_order)
            self.assertEqual(account.call("/courier/verification", "DELETE", {})[0], 200)
            self.assertEqual(account.call(f"/courier/verification/media/{target}/passport")[0], 404)
            self.assertFalse(account.call("/me")[1]["user"]["approved"])

        def test_21_stale_gps_blocks_claim_and_stops_shift(self):
            old = (dt.datetime.now(dt.timezone.utc) - dt.timedelta(minutes=10)).isoformat(timespec="milliseconds").replace("+00:00", "Z")
            target = self.loser.user["id"]
            self.application.execute("UPDATE users SET located_at=?,online=1 WHERE id=?", old, target)
            available = self.application.one("SELECT id FROM orders WHERE status='new' ORDER BY id DESC LIMIT 1")["id"]
            self.assertEqual(self.loser.call(f"/orders/{available}/claim", "POST", {})[0], 409)
            self.application.cleanup()
            self.assertFalse(self.loser.call("/me")[1]["user"]["online"])

